-- Real push notifications (owner request, 24 Oct 2026):
--  * Android phones: Firebase Cloud Messaging (FCM) device tokens;
--  * browsers: Web Push (VAPID). The VAPID key pair is generated by the
--    notifications worker on first use and kept in Vault — never in the repo;
--  * appointment reminders the day before and two hours before.
-- Texts stay generic (templates.ts); the details are only inside the app.

create table public.push_devices (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null references public.profiles (id) on delete cascade,
  kind text not null check (kind in ('fcm', 'web')),
  token text not null unique,                -- FCM token, or the Web Push endpoint URL
  web_keys jsonb,                            -- {p256dh, auth} for Web Push
  platform text,                             -- android / chrome / safari …
  created_at timestamptz not null default now(),
  last_seen_at timestamptz not null default now(),
  failures int not null default 0,
  disabled_at timestamptz,
  check (kind = 'fcm' or web_keys ? 'p256dh' and web_keys ? 'auth')
);
create index push_devices_user_idx on public.push_devices (user_id) where disabled_at is null;
alter table public.push_devices enable row level security;
create policy push_devices_own on public.push_devices for select to authenticated using (user_id = auth.uid());
grant select on public.push_devices to authenticated;

-- this phone / browser wants notifications for the signed-in user (re-registering moves the token)
create or replace function public.register_push_device(p_kind text, p_token text, p_platform text default null, p_web_keys jsonb default null)
returns void
language plpgsql
security definer
set search_path = ''
as $$
begin
  if auth.uid() is null then perform private.fail('not_authenticated'); end if;
  if p_kind not in ('fcm', 'web') or length(coalesce(p_token, '')) not between 20 and 2000 then perform private.fail('invalid_input'); end if;
  if p_kind = 'web' and (p_token !~ '^https://' or not (coalesce(p_web_keys, '{}'::jsonb) ? 'p256dh' and p_web_keys ? 'auth')) then
    perform private.fail('invalid_input');
  end if;
  insert into public.push_devices (user_id, kind, token, web_keys, platform)
  values (auth.uid(), p_kind, p_token, case when p_kind = 'web' then jsonb_build_object('p256dh', p_web_keys ->> 'p256dh', 'auth', p_web_keys ->> 'auth') end, left(p_platform, 40))
  on conflict (token) do update
    set user_id = auth.uid(), web_keys = excluded.web_keys, platform = excluded.platform,
        last_seen_at = now(), failures = 0, disabled_at = null;
end;
$$;

create or replace function public.unregister_push_device(p_token text)
returns void language sql security definer set search_path = '' as $$
  delete from public.push_devices where token = p_token and user_id = auth.uid();
$$;

-- the browser needs the public half of the VAPID key to subscribe
create or replace function public.web_push_public_key()
returns text language sql stable security definer set search_path = '' as $$
  select (decrypted_secret::jsonb) ->> 'public_key' from vault.decrypted_secrets where name = 'web_push_vapid' limit 1;
$$;

-- worker only: where to deliver, the VAPID keys, and housekeeping
create or replace function public.push_targets(p_user_id uuid)
returns jsonb language sql stable security definer set search_path = '' as $$
  select coalesce(jsonb_agg(jsonb_build_object('id', id, 'kind', kind, 'token', token, 'web_keys', web_keys)), '[]'::jsonb)
    from public.push_devices where user_id = p_user_id and disabled_at is null;
$$;

create or replace function public.push_vapid()
returns jsonb language sql stable security definer set search_path = '' as $$
  select decrypted_secret::jsonb from vault.decrypted_secrets where name = 'web_push_vapid' limit 1;
$$;

-- first run: the worker generates the key pair and stores it here (kept if one already exists)
create or replace function public.push_store_vapid(p_value jsonb)
returns jsonb language plpgsql security definer set search_path = '' as $$
begin
  if not exists (select 1 from vault.secrets where name = 'web_push_vapid') then
    perform vault.create_secret(p_value::text, 'web_push_vapid', 'Web Push VAPID key pair (generated by notifications-worker)');
  end if;
  return public.push_vapid();
end;
$$;

create or replace function public.push_device_result(p_id uuid, p_ok boolean, p_gone boolean default false)
returns void language sql security definer set search_path = '' as $$
  update public.push_devices
     set failures = case when p_ok then 0 else failures + 1 end,
         last_seen_at = case when p_ok then now() else last_seen_at end,
         disabled_at = case when p_gone or (not p_ok and failures >= 9) then now() else disabled_at end
   where id = p_id;
$$;

revoke execute on function public.register_push_device(text, text, text, jsonb), public.unregister_push_device(text),
  public.web_push_public_key() from public, anon;
grant execute on function public.register_push_device(text, text, text, jsonb), public.unregister_push_device(text),
  public.web_push_public_key() to authenticated;
revoke execute on function public.push_targets(uuid), public.push_vapid(), public.push_store_vapid(jsonb),
  public.push_device_result(uuid, boolean, boolean) from public, anon, authenticated;
grant execute on function public.push_targets(uuid), public.push_vapid(), public.push_store_vapid(jsonb),
  public.push_device_result(uuid, boolean, boolean) to service_role;

-- appointment reminders: the day before (18–30 h ahead) and two hours before (1–2.5 h ahead)
create or replace function public.queue_appointment_reminders()
returns int
language plpgsql
security definer
set search_path = ''
as $$
declare
  n int := 0;
  a record;
begin
  for a in
    select ap.id, ap.patient_id, ap.booking_number, lower(ap.period) as starts_at,
           case when lower(ap.period) - now() > interval '3 hours' then 'day' else 'soon' end as kind
      from public.appointments ap
     where ap.status = 'confirmed'
       and (lower(ap.period) between now() + interval '18 hours' and now() + interval '30 hours'
            or lower(ap.period) between now() + interval '1 hour' and now() + interval '150 minutes')
  loop
    n := n + private.notify_patient(a.patient_id, 'appointment.reminder_' || a.kind,
                                    jsonb_build_object('booking_number', a.booking_number, 'starts_at', a.starts_at),
                                    'apptrem:' || a.id || ':' || a.kind, array['in_app', 'push']::public.notification_channel[]);
  end loop;
  return n;
end;
$$;
revoke execute on function public.queue_appointment_reminders() from public, anon, authenticated;
grant execute on function public.queue_appointment_reminders() to service_role;

do $$ begin
  if exists (select 1 from pg_extension where extname = 'pg_cron') then
    perform cron.unschedule(jobid) from cron.job where jobname = 'appointment-reminders';
    perform cron.schedule('appointment-reminders', '*/10 * * * *', 'select public.queue_appointment_reminders()');
  end if;
end $$;
